class Bonus:
    def __init__(self, amount):
        self.amount = amount
        return amount

b = Bonus(100)
print(b.amount)

class Card:
    def __init__(self):
        self.__pin = "2468"

c = Card()
print(c.__pin)

class Account:
    def __init__(self, a, b):
        self.a = a
        self.b = b

    def calc(self):
        total = self.a + self.b

acc = Account(3, 4)
print(acc.calc())

class Vault:
    def __init__(self):
        self.__code = "777"

    def reveal(self):
        return self.__code

class Safe(Vault):
    def reveal(self):
        return "locked"

s = Safe()
v = Vault()
print(v.reveal())
print(s.reveal())
print(s._Vault__code)

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def __str__(self):
        return f"Point({self.x}, {self.y})"

p = Point(2, 5)
print(p)
print(str(p) == "Point(2, 5)")
